{% if posts %}
{% for post in posts.toArray() %}
{% if post.indexing == undefined or post.indexing %}

  {{ post.title }}
  {{ [url, post.path] | urlJoin | uriencode }}
  {% if content %}
  {{ post.content | plainText | safe }}
  {% endif %}

{% endif %}
{% endfor %}
{% endif %}
{% if pages %}
{% for page in pages.toArray() %}
{% if page.indexing == undefined or page.indexing %}

  {{ page.title }}
  {{ [url, page.path] | urlJoin | uriencode }}
  {% if content %}
  {{ page.content | plainText | safe }}
  {% endif %}

{% endif %}
{% endfor %}
{% endif %}
